"""Par-level inventory alerts for small restaurants (prototype)."""
from dataclasses import dataclass

@dataclass
class Item:
    name: str
    on_hand: float
    par: float
    unit_cost: float
    supplier: str

def reorder_list(items):
    """Return items below par, grouped by supplier, with order quantities."""
    orders = {}
    for it in items:
        if it.on_hand < it.par:
            qty = it.par - it.on_hand
            orders.setdefault(it.supplier, []).append((it.name, qty, round(qty * it.unit_cost, 2)))
    return orders

if __name__ == "__main__":
    demo = [
        Item("Chicken thigh (lb)", 4, 20, 2.10, "Valley Foods"),
        Item("Rice (lb)", 30, 25, 0.80, "Valley Foods"),
        Item("Tortillas (pack)", 2, 10, 1.50, "Mission Produce"),
    ]
    for supplier, lines in reorder_list(demo).items():
        print(supplier)
        for name, qty, cost in lines:
            print(f"  {name}: order {qty:g} (~${cost})")
EOF
